#include <stdio.h>
#include <stdlib.h>

#define MAXN 100005
#define MAXLOG 20
#define INF 1000000000

typedef struct {
    int u, v, p;
} Edge;

int cmpEdge(const void *a, const void *b) {
    const Edge *ea = (const Edge *)a;
    const Edge *eb = (const Edge *)b;
    if (ea->p != eb->p) return eb->p - ea->p;
    if (ea->u != eb->u) return ea->u - eb->u;
    return ea->v - eb->v;
}

int dsu[MAXN], sz[MAXN];

int find(int x) {
    while (dsu[x] != x) {
        dsu[x] = dsu[dsu[x]];
        x = dsu[x];
    }
    return x;
}

void unite(int a, int b) {
    a = find(a);
    b = find(b);
    if (a == b) return;
    if (sz[a] < sz[b]) {
        int t = a;
        a = b;
        b = t;
    }
    dsu[b] = a;
    sz[a] += sz[b];
}

int head[MAXN], to[2 * MAXN], nxt[2 * MAXN], wt[2 * MAXN];
int edgeCnt = 0;

void addEdge(int u, int v, int w) {
    to[edgeCnt] = v;
    wt[edgeCnt] = w;
    nxt[edgeCnt] = head[u];
    head[u] = edgeCnt++;

    to[edgeCnt] = u;
    wt[edgeCnt] = w;
    nxt[edgeCnt] = head[v];
    head[v] = edgeCnt++;
}

int up[MAXLOG][MAXN], mn[MAXLOG][MAXN], depth[MAXN];

int query(int u, int v) {
    int ans = INF;

    if (depth[u] < depth[v]) {
        int t = u;
        u = v;
        v = t;
    }

    int diff = depth[u] - depth[v];
    for (int k = 0; k < MAXLOG; k++) {
        if ((diff >> k) & 1) {
            if (mn[k][u] < ans) ans = mn[k][u];
            u = up[k][u];
        }
    }

    if (u == v) return ans;

    for (int k = MAXLOG - 1; k >= 0; k--) {
        if (up[k][u] != up[k][v]) {
            if (mn[k][u] < ans) ans = mn[k][u];
            if (mn[k][v] < ans) ans = mn[k][v];
            u = up[k][u];
            v = up[k][v];
        }
    }

    if (mn[0][u] < ans) ans = mn[0][u];
    if (mn[0][v] < ans) ans = mn[0][v];

    return ans;
}

int main(void) {
    int N, B;
    if (scanf("%d %d", &N, &B) != 2) return 0;

    Edge *edges = (Edge *)malloc(B * sizeof(Edge));
    for (int i = 0; i < B; i++) {
