    for (int i = 1; i <= N; i++) {
        dsu[i] = i;
        sz[i] = 1;
        head[i] = -1;
    }

    for (int i = 0; i < B; i++) {
        int u = edges[i].u;
        int v = edges[i].v;
        int p = edges[i].p;

        if (find(u) != find(v)) {
            unite(u, v);
            addEdge(u, v, p);
        }
    }

    free(edges);

    for (int k = 0; k < MAXLOG; k++) {
        for (int v = 1; v <= N; v++) {
            up[k][v] = v;
            mn[k][v] = INF;
        }
    }

    int stack[MAXN];
    int top = 0;

    depth[1] = 0;
    up[0][1] = 1;
    mn[0][1] = INF;
    stack[top++] = 1;

    while (top > 0) {
        int u = stack[--top];

        for (int e = head[u]; e != -1; e = nxt[e]) {
            int v = to[e];

            if (v == up[0][u]) continue;

            up[0][v] = u;
            depth[v] = depth[u] + 1;
            mn[0][v] = wt[e];
            stack[top++] = v;
        }
    }

    for (int k = 1; k < MAXLOG; k++) {
        for (int v = 1; v <= N; v++) {
            int mid = up[k - 1][v];
            up[k][v] = up[k - 1][mid];

            int a = mn[k - 1][v];
            int b = mn[k - 1][mid];
            mn[k][v] = a < b ? a : b;
        }
    }

    int C;
    scanf("%d", &C);

    for (int i = 0; i < C; i++) {
        int X, Y;
        scanf("%d %d", &X, &Y);
        printf("%d\n", query(X, Y));
